result=java.hexDecodeToString(result)
a=result.slice(4,6)
b=result.slice(6,8)
c=result.slice(8,10)
url=`https://vpx05.myself-bbs.com/hls/${a}/${b}/${c}/${result}/index.m3u8`
if(book.durChapterIndex == chapter.index){
java.startBrowser(url,chapter.title);
java.toast('正在加载视频...');
result = ' \n\n【刷新正文】跳转播放\n不要相信且不要点击视频里的任何广告，误触后请立即返回\n🔗直链:\n' + url}

